import test from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { RETIRED_BUILTIN_IDS } from "./retired-lists.ts";

const require = createRequire(import.meta.url);
const seedData = require("./builtin-vocabulary-data.json") as unknown;

// This file is the curated library: the lists every tester receives, and the
// only ones they can get, in the NEXT_PUBLIC_CURATED_LIBRARY build. It is
// regenerated by `npm run import:phone` from an in-app export, so the tests
// below guard the two things a regeneration can quietly get wrong.
//
// It used to ship 19 lists (Darija + Hebrew Quizlet units, 1080 words) carrying
// their original owner's real study progress, which every tester would have seen
// as their own. Hence the progress guard rather than a trust-the-script policy.

type SeedEntry = {
  id?: unknown;
  title?: unknown;
  terms?: unknown;
  items?: unknown;
  testHistory?: unknown;
};

const entries = (): SeedEntry[] => {
  assert.ok(Array.isArray(seedData), "the seed file must be a JSON array");
  return seedData as SeedEntry[];
};

test("the seed file is an array, so the module cannot crash at import time", () => {
  // lib/builtin-vocabulary.ts is evaluated at import time by the only page and
  // calls .map() on this data. An object here used to throw
  // "builtinVocabulary.map is not a function" during `next build` and at
  // hydration, with no error boundary to catch it. The module now guards with
  // Array.isArray, but keeping the data file's shape pinned is cheaper than
  // relying on the guard.
  assert.equal(Array.isArray(seedData), true);
});

test("every bundled list has an id and a title", () => {
  for (const entry of entries()) {
    assert.equal(typeof entry.id, "string", "a bundled list needs an id");
    assert.ok((entry.id as string).trim(), "a bundled list needs a non-empty id");
    assert.equal(typeof entry.title, "string");
    assert.ok((entry.title as string).trim());
  }
});

test("no bundled id is a retired one", () => {
  // A retired id is tombstoned on load (lib/retired-lists.ts), so reusing one
  // would make the list vanish from every library with no message at all —
  // `isRetiredBuiltinList` puts the tombstone ahead of the live bundle on
  // purpose, because the stored data under that id belongs to the old list.
  for (const entry of entries()) {
    assert.equal(
      RETIRED_BUILTIN_IDS.has(entry.id as string),
      false,
      `${String(entry.id)} is tombstoned — give the new list a fresh id`
    );
  }
});

test("bundled ids are unique", () => {
  const ids = entries().map((entry) => entry.id as string);
  assert.equal(new Set(ids).size, ids.length, "two bundled lists share an id");
});

test("the bundle ships content only — never anyone's progress", () => {
  // The shape IS the guard. lib/builtin-vocabulary.ts compiles `terms` through
  // `makeItems`, which hard-codes fresh cards (status "new", box 0, no
  // attempts); `items` goes through `makeSnapshotItems`, which preserves
  // whatever progress the JSON carries. So a bundle built from `terms` cannot
  // leak practice history even if the export it came from was full of it.
  for (const entry of entries()) {
    assert.ok(
      Array.isArray(entry.terms),
      `${String(entry.id)} must use "terms" (content only), not "items"`
    );
    assert.equal(
      entry.items,
      undefined,
      `${String(entry.id)} uses "items", which carries progress into the bundle`
    );
    assert.equal(
      entry.testHistory,
      undefined,
      `${String(entry.id)} carries testHistory — that is someone's quiz history`
    );

    for (const term of entry.terms as Array<Record<string, unknown>>) {
      assert.equal(typeof term.word, "string");
      assert.equal(typeof term.translation, "string");
      for (const progressField of [
        "status",
        "attempts",
        "correctCount",
        "wrongCount",
        "correctStreak",
        "wrongStreak",
        "box",
        "dueAt",
        "stability",
        "difficulty",
        "lastTestedAt",
        "lastWrongAt"
      ]) {
        assert.equal(
          progressField in term,
          false,
          `${String(entry.id)}: a bundled term must not carry "${progressField}"`
        );
      }
    }
  }
});

test("a bundled list has enough distinct answers for multiple choice", () => {
  // `canUseChoice` (lib/quiz-options.ts) needs 4 distinct translations, or the
  // choice-based modes fall back to written and sit there greyed out. A curated
  // list that cannot exercise them wastes half the thing testers are testing.
  for (const entry of entries()) {
    const answers = new Set(
      (entry.terms as Array<Record<string, unknown>>).map((term) =>
        String(term.translation)
      )
    );
    assert.ok(
      answers.size >= 4,
      `${String(entry.id)} has ${answers.size} distinct answers; choice modes need 4`
    );
  }
});
